// src/optimizer/utils/csv-with-header.ts
function splitCsvLine(line) {
  const fields = [];
  let current = "";
  let inQuotes = false;
  for (let i2 = 0; i2 < line.length; i2++) {
    const char = line[i2];
    if (char === '"') {
      if (inQuotes && line[i2 + 1] === '"') {
        current += '"';
        i2++;
      } else {
        inQuotes = !inQuotes;
      }
    } else if (char === "," && !inQuotes) {
      fields.push(current);
      current = "";
    } else {
      current += char;
    }
  }
  fields.push(current);
  return fields;
}
function parseCsvWithHeader(stdout) {
  const lines = stdout.split("\n").map((l) => l.replace(/\r$/, "")).filter((l) => l.trim());
  if (lines.length === 0) return [];
  const header = splitCsvLine(lines[0]).map((h) => h.trim().toLowerCase());
  const rows = [];
  for (const line of lines.slice(1)) {
    const fields = splitCsvLine(line);
    if (fields.length === header.length && fields[0]?.trim().toLowerCase() === header[0]) {
      continue;
    }
    const row = {};
    for (let i2 = 0; i2 < header.length; i2++)
      row[header[i2]] = (fields[i2] ?? "").trim();
    rows.push(row);
  }
  return rows;
}

